SELECT ss.store_id, CASE WHEN ss.revenue >= 4100 THEN 'high' WHEN ss.revenue >= 1900 THEN 'mid' ELSE 'low' END AS revenue_bucket, COUNT(i.quantity) AS quantity_count, COUNT(DISTINCT i.quantity) AS unique_products FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY ss.store_id, CASE WHEN ss.revenue >= 4100 THEN 'high' WHEN ss.revenue >= 1900 THEN 'mid' ELSE 'low' END ORDER BY unique_products DESC, store_id, revenue_bucket LIMIT 50;
